// ============================================================
// ScholarPath Phase 1
// Build the canonical profile enrichment object
// ============================================================

function getFirst(nodeName) {
  const items = $(nodeName).all();
  return items.length ? items[0].json : null;
}

function getAll(nodeName) {
  return $(nodeName).all().map(item => item.json);
}

// ------------------------------------------------------------
// 1. Supabase profile created earlier
// ------------------------------------------------------------

const profileRow = getFirst("Create a row");

if (!profileRow) {
  throw new Error("Create a row output is unavailable.");
}

const profileId =
  profileRow.id ||
  profileRow.data?.id;

if (!profileId) {
  throw new Error(
    "Supabase profile ID was not found in Create a row output."
  );
}

// ------------------------------------------------------------
// 2. CV extraction
// ------------------------------------------------------------

const cv = getFirst("Extract from File");

const rawCvText =
  cv?.text ||
  "";

if (!rawCvText.trim()) {
  throw new Error(
    "Extract From File returned no CV text."
  );
}

// ------------------------------------------------------------
// 3. GitHub user
// ------------------------------------------------------------

const githubUser = getFirst("GitHub User Info");

const normalizedUser = githubUser?.login
  ? {
      login: githubUser.login,
      id: githubUser.id,
      name: githubUser.name,
      bio: githubUser.bio,
      company: githubUser.company,
      location: githubUser.location,
      blog: githubUser.blog,
      public_repos: githubUser.public_repos,
      public_gists: githubUser.public_gists,
      followers: githubUser.followers,
      following: githubUser.following,
      html_url: githubUser.html_url
    }
  : null;

// ------------------------------------------------------------
// 4. GitHub repositories
// ------------------------------------------------------------

const repoItems = getAll("GitHub Repos");

const repos = repoItems
  .filter(repo => repo?.name)
  .map(repo => ({
    name: repo.name,
    full_name: repo.full_name,
    description: repo.description,
    html_url: repo.html_url,
    language: repo.language,
    stargazers_count: repo.stargazers_count,
    forks_count: repo.forks_count,
    topics: repo.topics || [],
    created_at: repo.created_at,
    updated_at: repo.updated_at,
    private: repo.private
  }));

// ------------------------------------------------------------
// 5. Calculate languages
// ------------------------------------------------------------

const languageCounts = {};

for (const repo of repos) {
  if (!repo.language) continue;

  languageCounts[repo.language] =
    (languageCounts[repo.language] || 0) + 1;
}

const languages = Object.entries(languageCounts)
  .sort((a, b) => b[1] - a[1])
  .map(([language, repository_count]) => ({
    language,
    repository_count
  }));

// ------------------------------------------------------------
// 6. Final canonical object
// ------------------------------------------------------------

return [
  {
    json: {
      profile_id: profileId,

      raw_cv_text: rawCvText,

      github_data: normalizedUser
        ? {
            user: normalizedUser,
            repos,
            languages
          }
        : null,

      metadata: {
        cv_available: true,
        github_available: !!normalizedUser,
        repository_count: repos.length,
        language_count: languages.length
      }
    }
  }
];

