let raw = null;

try {
  // Gemini response
  raw = $json?.candidates?.[0]?.content?.parts?.[0]?.text;

  if (!raw) {
    throw new Error('Gemini returned no text content');
  }

  // Remove markdown fences if present
  const cleaned = raw
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const recommendations = JSON.parse(cleaned);

  // Validate expected structure
  if (!recommendations || !Array.isArray(recommendations.recommendations)) {
    throw new Error(
      'Invalid Gemini JSON: recommendations array is missing'
    );
  }

  if (recommendations.recommendations.length === 0) {
    throw new Error(
      'Gemini returned an empty recommendations array'
    );
  }

  return {
    json: {
      profile_id: $('Create a row').first().json.id,
      structured_profile: recommendations,
      _parse_error: false
    }
  };

} catch (err) {

  return {
    json: {
      profile_id: $('Create a row').first().json.id,
      structured_profile: null,
      _parse_error: true,
      message: err.message,
      raw: raw
    }
  };
}
